#include <bits/stdc++.h>
#define fi first
#define se second
using namespace std;

const int MAX_SIZE = 5500;
const long long INF_VAL = 1e9 + 7;

int n, m, k, c, d;
int start_node, end_node, total_flow = 0, s = MAX_SIZE - 2, t = MAX_SIZE - 1, parent[MAX_SIZE];
long long total_cost = 0, dist[MAX_SIZE];
priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;

struct Edge {
    int v, c;
    int index, cap;
};
vector<Edge> graph[MAX_SIZE];

void addEdge(int u, int v, int cost, int capacity) {
    int sizeU = graph[u].size(), sizeV = graph[v].size();
    graph[u].push_back({v, cost, sizeV, capacity});
    graph[v].push_back({u, -cost, sizeU, 0});
}

void findShortestPath() {
    fill(dist, dist + MAX_SIZE, INF_VAL);
    pq.push({dist[s] = 0, s});
    while (!pq.empty()) {
        auto [currDist, node] = pq.top(); pq.pop();
        if (currDist > dist[node]) continue;
        for (auto &edge : graph[node]) {
            if (edge.cap > 0 && dist[edge.v] > currDist + edge.c) {
                parent[edge.v] = edge.index;
                dist[edge.v] = currDist + edge.c;
                pq.push({dist[edge.v], edge.v});
            }
        }
    }
}

void increaseFlow() {
    int flowIncrement = k, v = t;
    while (v != s) {
        int u = graph[v][parent[v]].v;
        int ind = graph[v][parent[v]].index;
        flowIncrement = min(flowIncrement, graph[u][ind].cap);
        v = u;
    }
    total_flow += flowIncrement;
    total_cost += (long long)flowIncrement * dist[t];
    v = t;
    while (v != s) {
        int u = graph[v][parent[v]].v;
        int ind = graph[v][parent[v]].index;
        graph[v][parent[v]].cap += flowIncrement;
        graph[u][ind].cap -= flowIncrement;
        v = u;
    }
}

int nodeNumber(int u, int t) {
    return u + t * n;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> k >> c >> d;
    start_node = n + k;
    for (int i = 0; i < k; i++) {
        cin >> u;
        addEdge(s, nodeNumber(u, 0), 0, 1);
    }
    for (int i = 0; i <= n + k; i++)
        addEdge(nodeNumber(1, i), t, c * i, k);
    for (int i = 1; i <= n; i++)
        for (int j = 0; j < n + k; j++)
            addEdge(nodeNumber(i, j), nodeNumber(i, j + 1), 0, k);
    for (int i = 0; i < m; i++) {
        cin >> u >> v;
        for (int j = 0; j < k; j++) {
            for (int l = 0; l < n + k; l++) {
                addEdge(nodeNumber(u, l), nodeNumber(v, l + 1), d * (2 * j + 1), 1);
                addEdge(nodeNumber(v, l), nodeNumber(u, l + 1), d * (2 * j + 1), 1);
            }
        }
    }
    while (total_flow < k) {
        findShortestPath();
        increaseFlow();
    }
    cout << total_cost;
}
